Title: Loosing params consistency in child routes with mergeParams
Description: Hi folks,

I'm facing an issue which is that if I nest 2 routers like in the example below, my modifications on the `req.params` object are not kept in the child route. Any thought on how to resolve it ?

``` js
var express = require('express');

module.exports = function(app) {

    var myRouter = express.Router();
    var mySpecificRouter = express.Router({
        mergeParams: true
    });

    myRouter.all('*', app.requestHelper.verifyToken);

    myRouter.route('/')
        .get(app.controller.my.list);

    myRouter
        .use('/:id', function(req, res, next) {
            if (/^[0-9]+$/.test(req.params.id)) {
                console.log('parent params before parsing', req.params);
                req.params.id = parseInt(req.params.id, 10);
                console.log('parent params', req.params);
                next();
            } else {
                app.status(400).send({error:'bad request'});
            }
        }, mySpecificRouter);

    mySpecificRouter
        .route('/')
        .get(function(req, res, next) {
            console.log('child params', req.params);
            app.status(200).send({});
        });

    app.use('/route', myRouter);
};
```

So the console log of a get request on /route/101 give me the following:

```
parent params before parsing {id: '100'}
parent params {id: 100}
child params {id: '101'}
```

When I check in the `parentParams` in the index of the router I see the original object instead of the altered one...

Thanks !


